mapper.select:
SELECT DEAL.TRADE_ID as seqno, DEAL.BOOK_DATE as bookDate, DEAL.BOOKSET_ID AS booksetId, BB.BOOKSET_NAME as booksetName, DEAL.BOOK_ID as bookId, DEAL.BUSI_DETAIL_TYPE as tableId,
DETAIL.SUBJECT_NO AS subjectNo, DETAIL.SUBJECT_NAME AS subjectName, DETAIL.DETAIL_SUBJECT_NO_TAIL AS detailSubjectNo, DETAIL.DETAIL_SUBNAME_TAIL AS detailSubjectName, DETAIL.CD_FLAG AS cdFlag, DETAIL.CCY AS ccy, DETAIL.O_HAPPEN_AMT as happenAmt, DETAIL.HAPPEN_NUMBER as happenNumber,
DEAL.BUSI_TYPE as busiType, DEAL.BUSI_ID as busiId, FP.FINPROD_ABBR as busiName, DEAL.TRADE_ID as tradeId, DEAL.P_TRADE_ID AS pTradeId, DEAL.OFFSET_FLAG AS offsetFlag, DEAL.BOOK_REMARK as bookRemark, to_char(bbd.BOOKSET_DATE,'yyyy-MM-dd') as booksetDate, DEAL.CREATE_USER as createUser FROM TRD_VOUCH_DEAL DEAL LEFT JOIN TRD_VOUCH_DEAL_DETAIL DETAIL ON DEAL.TRADE_ID = DETAIL.TRADE_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = DEAL.BUSI_ID AND DEAL.BUSI_DETAIL_TYPE = FP.FINPROD_TYPE LEFT JOIN BOK_BOOKSET BB ON BB.BOOKSET_ID = DEAL.BOOKSET_ID left join BOK_BOOKSET_DATE bbd on bbd.BOOKSET_ID=BB.BOOKSET_ID WHERE BB.BOOKSET_TYPE = #{booksetType}
AND DEAL.BOOKSET_ID in
#{booksetId }
AND DEAL.BUSI_DETAIL_TYPE = #{finprodType}
AND DEAL.BUSI_ID LIKE '%' || #{busiId} || '%'
AND DEAL.BOOK_DATE >= #{bookDateBegin}
AND DEAL.BOOK_DATE <= #{bookDateEnd}
AND DEAL.TRADE_ID LIKE '%' || #{tradeId} || '%'
AND DEAL.BOOK_ID LIKE '%' || #{bookId} || '%'
AND DEAL.BOOK_TYPE = #{bookType}
GROUP BY DEAL.TRADE_ID, DEAL.BOOK_DATE, DEAL.BOOKSET_ID, BB.BOOKSET_NAME, DEAL.BOOK_ID, DEAL.BUSI_DETAIL_TYPE,
DETAIL.SUBJECT_NO, DETAIL.SUBJECT_NAME, DETAIL.DETAIL_SUBJECT_NO_TAIL, DETAIL.DETAIL_SUBNAME_TAIL, DETAIL.CD_FLAG, DETAIL.CCY, DETAIL.O_HAPPEN_AMT, DETAIL.HAPPEN_NUMBER,
DEAL.BUSI_TYPE, DEAL.BUSI_ID, FP.FINPROD_ABBR, DEAL.TRADE_ID, DEAL.P_TRADE_ID, DEAL.OFFSET_FLAG, DEAL.BOOK_REMARK, bbd.BOOKSET_DATE, DEAL.CREATE_USER ORDER BY DEAL.BOOK_DATE DESC, DEAL.BOOK_ID DESC
